<script setup>
import {ref,onMounted}from'vue';import api from'../services/api.js';import PageHero from'../components/PageHero.vue';import DestinationCard from'../components/DestinationCard.vue'
const items=ref([]),loading=ref(true),keyword=ref(''),type=ref('');const load=async()=>{loading.value=true;try{items.value=await api.get('/public/destinations',{params:{keyword:keyword.value||undefined,type:type.value||undefined}})}finally{loading.value=false}};onMounted(load)
</script>
<template><PageHero image="/uploads/demo/banners/banner-004.png" eyebrow="DESTINATIONS" title="从目的地开始，遇见一段路" subtitle="城市、海岛、古镇与山水。先选一个心里想去的方向，再把行程慢慢补完整。"/><div class="container destination-page"><div class="destination-search"><el-input v-model="keyword" size="large" placeholder="搜索城市或风景" clearable @keyup.enter="load"/><el-select v-model="type" size="large" placeholder="目的地类型" clearable><el-option label="城市" value="CITY"/><el-option label="海岛" value="ISLAND"/><el-option label="古镇" value="ANCIENT_TOWN"/><el-option label="自然保护区" value="NATURE"/></el-select><el-button type="primary" size="large" @click="load">查找目的地</el-button></div><div class="result-note"><b>{{items.length}}</b> 个目的地，等待被写进下一次计划</div><div v-loading="loading" class="destination-grid all"><DestinationCard v-for="item in items" :key="item.id" :item="item"/></div></div></template>
<style scoped>.destination-page{padding:38px 0 80px}.destination-search{display:grid;grid-template-columns:1fr 220px 140px;gap:12px;padding:18px;background:white;border:1px solid #dde8e7;border-radius:16px}.result-note{margin:30px 0 18px;color:#71868a}.result-note b{font-size:24px;color:#167c8c}.destination-grid.all{grid-template-columns:repeat(3,1fr)}.destination-grid.all :deep(.destination-card){grid-column:auto;height:330px}@media(max-width:700px){.destination-search{grid-template-columns:1fr}.destination-grid.all{grid-template-columns:1fr}}</style>

